update lessons set objective_ar='أكتب نصًّا إقناعيًّا أثبت فيه أن الوطن ضرورة ملحّة للإنسان، أدعم رأيي بحجج وأدلة من الكتب والتجارب، وأردّ على الرأي المخالف، وأوظّف التشبيه المفصّل والمجمل، وأراجعه بمقياس.' where code='AR-Y8-N-T3-L10';
update success_criteria set statement_ar='أكتب فقرة إقناعية برأي وحجّتين.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L10');
update success_criteria set statement_ar='أكتب نصًّا من ثلاث فقرات: رأي، وحجج، وخاتمة، وأوظّف التشبيه.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L10');
update success_criteria set statement_ar='أكتب نصًّا إقناعيًّا متماسكًا يردّ على الرأي المخالف، وأراجعه بمقياس وأنشره.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L10');
update lesson_summaries set content=content||'{"hook": "إنسان بلا وطن… كيف يعيش؟ لماذا الوطن ضرورة؟", "idea": "يكتب الطالب نصًّا إقناعيًّا يثبت فيه أن الوطن ضرورة ملحّة للإنسان، بحجج وأدلة وتشبيهات موظّفة، ثم يراجعه بمقياس.", "learn": [["🗣️", "رأي واضح."], ["🧱", "حجج مدعومة بأدلة."], ["↩️", "ردّ على الرأي المخالف."], ["🎨", "تشبيه مفصّل أو مجمل."], ["📏", "أراجع بالمقياس."]], "quiz": [["التشبيه المفصّل يُذكر فيه وجه الشبه.", true], ["النص الإقناعي لا يحتاج إلى أدلة.", false]]}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T3-L10');